using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class ActorInspectorOperations
{
    private readonly ActorMediaExportOperations _mediaExport=new();
    private static void RefreshFilesystem(){var script=GD.Load<GDScript>("res://scripts/Globals/local_project_filesystem.gd");if(script.Get("node").AsGodotObject()!=null)script.Call("update_root_folder");}
    public Settings prepare_file_save(Resource property,Variant value){var extensions=Extensions(property);if(extensions.Length==0)return new Settings();string extension=value.VariantType==Variant.Type.String?value.AsString().GetExtension().ToLowerInvariant():extensions[0];if(value.VariantType==Variant.Type.Object&&value.AsGodotObject() is Resource reference&&ActorDataOperations.ScriptIs(reference,"res://scripts/actors/core/actor_object_reference.gd"))extension="tres";if(!extensions.Contains(extension))extension=extensions[0];string suggested=file_resource_display_name(value).GetBaseName();if(suggested.StartsWith("<",StringComparison.Ordinal))suggested=file_resource_type_name(property);var formats=_mediaExport.formats(property,value);if(formats.Length==0)return new Settings();if(!formats.Contains(extension))extension=formats[0];return new Settings{["title"]="Save "+file_resource_type_name(property),["suggested"]=suggested,["extension"]=extension,["embed"]=!extensions.Contains("mp4"),["formats"]=formats};}
    public Settings begin_file_save(Control owner,Resource property,Variant value,Variant setter,Settings result){if(result.GetValueOrDefault("cancelled",true).AsBool())return new Settings();if(result.GetValueOrDefault("embedded",false).AsBool()){var embedded=file_resource_to_embedded(value,property);if(embedded!=null){Invoke(owner,setter,embedded);if(is_shader_property(property))open_shader_resource(owner,embedded,false,default);}return new Settings();}string path=result.GetValueOrDefault("path","").AsString();if(path.Length==0)return new Settings();if(is_mesh_property(property)){var embedded=file_resource_to_embedded(value,property);value=embedded!=null?Variant.From(embedded):default;}var extensions=Extensions(property);bool media=extensions.Any(e=>e is "mp4" or "mp3" or "png")||value.VariantType==Variant.Type.Object&&value.AsGodotObject() is Resource reference&&ActorDataOperations.ScriptIs(reference,"res://scripts/actors/core/actor_object_reference.gd");return new Settings{["path"]=path,["value"]=value,["media"]=media};}
    public void finish_file_save(Control owner,Resource property,Variant setter,Settings request,bool success){if(!success)return;var extensions=Extensions(property);string path=request["path"].AsString();if(!extensions.Contains("mp4")&&!extensions.Contains("mp3"))Invoke(owner,setter,path);RefreshFilesystem();if(is_shader_property(property))open_shader_resource(owner,path,false,default);}
    public Settings prepare_object_save(Resource actor,Resource property,Resource definition,Resource data)=>new(){["title"]="Save "+definition.Get("display_name").AsString(),["suggested"]=actor.Get("display_name").AsString()+" "+definition.Get("display_name").AsString(),["formats"]=_mediaExport.formats(property,data)};
    public Settings begin_object_save(Control owner,Resource actor,Resource? parent,Resource definition,Resource property,Resource data,Settings result){if(result.GetValueOrDefault("cancelled",true).AsBool())return new Settings();if(result.GetValueOrDefault("embedded",false).AsBool()){AssignReference(owner,actor,parent,definition,property,_data.from_object(_data.copy_object(data)));return new Settings();}string path=result.GetValueOrDefault("path","").AsString();return path.Length>0?new Settings{["path"]=path,["value"]=_data.copy_object(data)}:new Settings();}
    public void finish_object_save(Control owner,Resource actor,Resource? parent,Resource definition,Resource property,Settings request,bool success){if(!success)return;string path=request["path"].AsString();if(parent==null)assign_object_resource_path(owner,actor,definition,property,path);else assign_nested_object_resource_path(owner,path,actor,parent,definition,property);RefreshFilesystem();owner.Call("_rebuild_selected");}
    public Settings prepare_project_file(Resource property){var extensions=Extensions(property);if(extensions.Length==0)return new Settings();return new Settings{["extension"]=extensions[0].TrimStart('.').ToLowerInvariant(),["suggested"]=property.Get("options").AsGodotDictionary().GetValueOrDefault("new_file_name","New "+property.Get("label").AsString())};}
    public string finish_project_file(Resource property,Settings result){if(result.GetValueOrDefault("cancelled",true).AsBool())return "";string path=result.GetValueOrDefault("path","").AsString();if(path.Length==0)return "";using var file=FileAccess.Open(path,FileAccess.ModeFlags.Write);if(file==null)return "";file.StoreString(property.Get("options").AsGodotDictionary().GetValueOrDefault("new_file_template","").AsString());file.Close();RefreshFilesystem();return path;}
}
